import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../../core/database/app_database.dart';
import '../buildings/buildings_page.dart';
class ProjectsPage extends StatefulWidget{const ProjectsPage({super.key});@override State<ProjectsPage> createState()=>_ProjectsPageState();}
class _ProjectsPageState extends State<ProjectsPage>{List<Map<String,dynamic>> rows=[];@override void initState(){super.initState();load();}Future<void> load()async{rows=await AppDatabase.instance.query('projects',order:'createdAt DESC');if(mounted)setState((){});}Future<void> edit([Map<String,dynamic>? x])async{final n=TextEditingController(text:x?['name']?.toString()??''),l=TextEditingController(text:x?['location']?.toString()??''),p=TextEditingController(text:x?['purpose']?.toString()??'');final ok=await showDialog<bool>(context:context,builder:(dialogContext)=>AlertDialog(title:Text(x==null?'مشروع جديد':'تعديل المشروع'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'الاسم')),TextField(controller:l,decoration:const InputDecoration(labelText:'الموقع')),TextField(controller:p,decoration:const InputDecoration(labelText:'غرض التقييم'))]),actions:[TextButton(onPressed:()=>Navigator.pop(dialogContext,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(dialogContext,true),child:const Text('حفظ'))]));if(ok==true&&n.text.trim().isNotEmpty){final data=<String,dynamic>{'name':n.text.trim(),'location':l.text.trim(),'purpose':p.text.trim()};if(x==null){data.addAll({'id':const Uuid().v4(),'createdAt':DateTime.now().toIso8601String()});await AppDatabase.instance.insert('projects',data);}else{await AppDatabase.instance.update('projects',data,'id=?',[x['id']]);}await load();}}
Future<void> remove(Map<String,dynamic>x)async{await AppDatabase.instance.delete('projects','id=?',[x['id']]);await load();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('المشروعات')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>edit(),icon:const Icon(Icons.add),label:const Text('مشروع')),body:rows.isEmpty?const Center(child:Text('لا توجد مشروعات')):RefreshIndicator(onRefresh:load,child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:rows.length,itemBuilder:(context,i){final x=rows[i];return Card(child:ListTile(leading:const Icon(Icons.business),title:Text('${x['name']}'),subtitle:Text('${x['location']}\n${x['purpose']}'),isThreeLine:true,onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>BuildingsPage(project:x))).then((_)=>load()),trailing:PopupMenuButton<String>(itemBuilder:(context)=>const[PopupMenuItem(value:'edit',child:Text('تعديل')),PopupMenuItem(value:'delete',child:Text('حذف'))],onSelected:(v){if(v=='edit'){edit(x);}else{remove(x);}})));})));}
